//! Translations: gettext catalogs embedded at build time. build.rs
//! compiles every `po/<lang>.po` into an .mo and lists the pairs in
//! OUT_DIR/locale_manifest.rs; init() detects the active language from
//! the environment and parses that catalog once. Untranslated strings
//! fall back to the English msgid, so partial catalogs are safe and a
//! build with no po/ files at all is simply an English build.

use gettext::Catalog;
use std::sync::OnceLock;

/// (language code, embedded .mo bytes) pairs generated by build.rs.
include!(concat!(env!("OUT_DIR"), "/locale_manifest.rs"));

static CATALOG: OnceLock<Option<Catalog>> = OnceLock::new();

/// Detect the user's language and load the best embedded catalog. Must
/// run before any translatable string is shown (call from main).
pub fn init() {
    CATALOG.get_or_init(|| {
        for want in requested_languages() {
            // Exact ("pt_BR") then base ("pt") match against what ships.
            let base = want.split('_').next().unwrap_or_default();
            for key in [want.as_str(), base] {
                if key.is_empty() {
                    continue;
                }
                if let Some((_, bytes)) = EMBEDDED_LOCALES.iter().find(|(l, _)| *l == key) {
                    return Catalog::parse(*bytes).ok();
                }
            }
        }
        None
    });
}

/// Language tags from the environment, most specific first, normalized
/// ("de_DE.UTF-8" → "de_DE"). LANGUAGE's colon-separated list comes
/// first so a user preference like "fr:de" tries French before German;
/// "C" and "POSIX" mean English and are dropped.
fn requested_languages() -> Vec<String> {
    let mut out = Vec::new();
    if let Ok(v) = std::env::var("LANGUAGE") {
        push_language_list(&v, &mut out);
    }
    for var in ["LC_ALL", "LC_MESSAGES", "LANG"] {
        if let Ok(v) = std::env::var(var) {
            push_language_list(&v, &mut out);
        }
    }
    out
}

fn push_language_list(value: &str, out: &mut Vec<String>) {
    for tag in value.split(':') {
        let tag = tag.trim();
        if tag.is_empty() || tag == "C" || tag == "POSIX" {
            continue;
        }
        // Charset and modifier are not part of a catalog name.
        let base = tag.split(['.', '@']).next().unwrap_or_default().trim();
        if !base.is_empty() && !out.iter().any(|o| o == base) {
            out.push(base.to_owned());
        }
    }
}

fn catalog() -> Option<&'static Catalog> {
    CATALOG.get().and_then(|c| c.as_ref())
}

/// Translate `msgid`.
pub fn i18n(msg: &str) -> String {
    catalog()
        .map(|c| c.gettext(msg).to_owned())
        .unwrap_or_else(|| msg.to_owned())
}

/// Translate `msgid` and fill the `{}` placeholders with `args`, in
/// order. Translations must keep the placeholders and their order.
pub fn i18n_f(msg: &str, args: &[&str]) -> String {
    let mut s = i18n(msg);
    for a in args {
        s = s.replacen("{}", a, 1);
    }
    s
}

/// Translate with plural forms; `{}` becomes the plain count.
pub fn i18n_n(singular: &str, plural: &str, n: u64) -> String {
    let s = raw_ngettext(singular, plural, n);
    s.replace("{}", &n.to_string())
}

/// Like i18n_n, but `{}` becomes `formatted` (e.g. locale-grouped
/// digits); the plural form is still chosen by the numeric count.
pub fn i18n_nf(singular: &str, plural: &str, n: u64, formatted: &str) -> String {
    let s = raw_ngettext(singular, plural, n);
    s.replace("{}", formatted)
}

fn raw_ngettext(singular: &str, plural: &str, n: u64) -> String {
    catalog()
        .map(|c| c.ngettext(singular, plural, n).to_owned())
        .unwrap_or_else(|| {
            if n == 1 {
                singular.to_owned()
            } else {
                plural.to_owned()
            }
        })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn untranslated_falls_back_to_msgid() {
        // Whatever the environment says, an unknown language leaves the
        // English msgid in place and leaves {} untouched helpers replace.
        assert_eq!(i18n("no such msgid anywhere"), "no such msgid anywhere");
        assert_eq!(i18n_f("{} of {}", &["1", "2"]), "1 of 2");
        assert_eq!(i18n_n("{} word", "{} words", 0), "0 words");
        assert_eq!(i18n_n("{} word", "{} words", 1), "1 word");
        assert_eq!(i18n_nf("{} word", "{} words", 5, "5 005"), "5 005 words");
    }

    #[test]
    fn language_list_parsing() {
        let mut out = Vec::new();
        push_language_list("de_DE.UTF-8:fr", &mut out);
        assert_eq!(out, ["de_DE", "fr"]);
        out.clear();
        push_language_list("C:POSIX:en_US@cyrillic:en_GB.utf8", &mut out);
        assert_eq!(out, ["en_US", "en_GB"]);
        out.clear();
        push_language_list("", &mut out);
        assert!(out.is_empty());
    }
}
